var pkg = require( './../package.json' ).name;
var cneg = require( './../lib' );


// MAIN //

bench( pkg, function benchmark( b ) {
	var values;
	var z;
	var y;
	var i;

	values = [
		new Complex128( uniform( -500.0, 500.0 ), uniform( -500.0, 500.0 ) ),
		new Complex128( uniform( -500.0, 500.0 ), uniform( -500.0, 500.0 ) )
	];

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		z = values[ i%values.length ];
		y = cneg( z );
		if ( typeof y !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isComplex128( y ) ) {
		b.fail( 'should return a Complex128' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});","lineStart":1,"lineEnd":58,"totalLines":58,"truncated":false}},"title":"repos/pc-lib-3456/complex-float64-base-neg/benchmark/benchmark.js","time":{"start":1783262362981,"end":1783262362983}},"id":"prt_f32b83c69001GkAf5xDa60FYWq","sessionID":"ses_0cd4835fbffei4ZY4TDRxRxps4","messageID":"msg_f32b832b0001rUB6nd48UqemOJ"}}

